#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
void line_up(const char*name,unsigned n,char*out,size_t size){unsigned m=n%100;const char*s="th";if(m<11||m>13){if(n%10==1)s="st";if(n%10==2)s="nd";if(n%10==3)s="rd";}snprintf(out,size,"%s, you are the %u%s customer we serve today. Thank you!",name,n,s);}

